#include <stdio.h>
#include <string.h>
#include "vm.h"

void vm_init(VM *vm) {
    memset(vm, 0, sizeof(*vm));
    vm->running = 1;
}

void vm_load(VM *vm, const uint8_t *code, int32_t len) {
    if (len > CODE_SIZE) len = CODE_SIZE;
    memcpy(vm->code, code, len);
    vm->code_len = len;
}

void vm_set_trace(VM *vm, int trace) { vm->trace = trace; }
void vm_stats_print(VM *vm) { (void)vm; }
void vm_stats_reset(VM *vm) { (void)vm; }

static int push(VM *vm, int32_t v) {
    if (vm->sp >= STACK_SIZE) {
        fprintf(stderr, "Stack overflow\n");
        return -1;
    }
    vm->stack[vm->sp++] = v;
    return 0;
}

static int pop(VM *vm, int32_t *out) {
    if (vm->sp <= 0) {
        fprintf(stderr, "Stack underflow\n");
        return -1;
    }
    *out = vm->stack[--vm->sp];
    return 0;
}

int vm_run(VM *vm) {
    if (!vm->running) return 0;
    while (vm->running) {
        if (vm->pc < 0 || vm->pc >= vm->code_len) {
            fprintf(stderr, "PC out of bounds: %d\n", vm->pc);
            return 1;
        }
        uint8_t op = vm->code[vm->pc++];
        int32_t a, b, v, addr;
        uint8_t idx;
        switch (op) {
        case OP_HALT:
            vm->running = 0;
            break;
        case OP_PUSH:
            if (vm->pc + 4 > vm->code_len) {
                fprintf(stderr, "Unexpected EOF\n");
                return 1;
            }
            memcpy(&v, vm->code + vm->pc, 4);
            vm->pc += 4;
            if (push(vm, v)) return 1;
            break;
        case OP_POP:
            if (pop(vm, &v)) return 1;
            break;
        case OP_DUP:
            if (vm->sp <= 0) { fprintf(stderr, "Stack underflow\n"); return 1; }
            if (push(vm, vm->stack[vm->sp - 1])) return 1;
            break;
        case OP_SWAP:
            if (vm->sp < 2) { fprintf(stderr, "Stack underflow\n"); return 1; }
            v = vm->stack[vm->sp - 1];
            vm->stack[vm->sp - 1] = vm->stack[vm->sp - 2];
            vm->stack[vm->sp - 2] = v;
            break;
        case OP_ADD:
            if (pop(vm, &b) || pop(vm, &a)) return 1;
            if (push(vm, a + b)) return 1;
            break;
        case OP_SUB:
            if (pop(vm, &b) || pop(vm, &a)) return 1;
            if (push(vm, a - b)) return 1;
            break;
        case OP_MUL:
            if (pop(vm, &b) || pop(vm, &a)) return 1;
            if (push(vm, a * b)) return 1;
            break;
        case OP_DIV:
            if (pop(vm, &b) || pop(vm, &a)) return 1;
            if (b == 0) { fprintf(stderr, "Division by zero\n"); return 1; }
            if (push(vm, a / b)) return 1;
            break;
        case OP_MOD:
            if (pop(vm, &b) || pop(vm, &a)) return 1;
            if (b == 0) { fprintf(stderr, "Modulo by zero\n"); return 1; }
            if (push(vm, a % b)) return 1;
            break;
        case OP_EQ:
            if (pop(vm, &b) || pop(vm, &a)) return 1;
            if (push(vm, a == b)) return 1;
            break;
        case OP_NE:
            if (pop(vm, &b) || pop(vm, &a)) return 1;
            if (push(vm, a != b)) return 1;
            break;
        case OP_LT:
            if (pop(vm, &b) || pop(vm, &a)) return 1;
            if (push(vm, a < b)) return 1;
            break;
        case OP_GT:
            if (pop(vm, &b) || pop(vm, &a)) return 1;
            if (push(vm, a > b)) return 1;
            break;
        case OP_LE:
            if (pop(vm, &b) || pop(vm, &a)) return 1;
            if (push(vm, a <= b)) return 1;
            break;
        case OP_GE:
            if (pop(vm, &b) || pop(vm, &a)) return 1;
            if (push(vm, a >= b)) return 1;
            break;
        case OP_JMP:
            memcpy(&addr, vm->code + vm->pc, 4);
            vm->pc = addr;
            break;
        case OP_JZ:
            memcpy(&addr, vm->code + vm->pc, 4);
            vm->pc += 4;
            if (pop(vm, &v)) return 1;
            if (v == 0) vm->pc = addr;
            break;
        case OP_JNZ:
            memcpy(&addr, vm->code + vm->pc, 4);
            vm->pc += 4;
            if (pop(vm, &v)) return 1;
            if (v != 0) vm->pc = addr;
            break;
        case OP_CALL:
            memcpy(&addr, vm->code + vm->pc, 4);
            vm->pc += 4;
            if (vm->cp >= CALL_STACK_SIZE) {
                fprintf(stderr, "Call stack overflow\n");
                return 1;
            }
            vm->call_stack[vm->cp++] = vm->pc;
            vm->pc = addr;
            break;
        case OP_RET:
            if (vm->cp <= 0) {
                fprintf(stderr, "Call stack underflow\n");
                return 1;
            }
            vm->pc = vm->call_stack[--vm->cp];
            break;
        case OP_LOAD:
            idx = vm->code[vm->pc++];
            if (push(vm, vm->locals[idx])) return 1;
            break;
        case OP_STORE:
            idx = vm->code[vm->pc++];
            if (pop(vm, &v)) return 1;
            vm->locals[idx] = v;
            break;
        case OP_PRINT:
            if (pop(vm, &v)) return 1;
            printf("%d\n", v);
            break;
        default:
            fprintf(stderr, "Unknown opcode: %u at pc=%d\n", op, vm->pc - 1);
            return 1;
        }
    }
    return 0;
}
