cat > /app/asm.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include "asm.h"
#include "vm.h"

void asm_init(Assembler *a) {
    memset(a, 0, sizeof(*a));
}

const uint8_t *asm_get_code(Assembler *a) { return a->code; }
int32_t asm_get_code_len(Assembler *a) { return a->code_len; }

static int emit_byte(Assembler *a, uint8_t b) {
    if (a->code_len >= ASM_CODE_SIZE) {
        fprintf(stderr, "Code buffer overflow\n");
        return -1;
    }
    a->code[a->code_len++] = b;
    return 0;
}

static int emit_i32(Assembler *a, int32_t v) {
    for (int i = 0; i < 4; i++) {
        if (emit_byte(a, (uint8_t)((v >> (8 * i)) & 0xff))) return -1;
    }
    return 0;
}

static int find_label(Assembler *a, const char *name, int32_t *out) {
    for (int i = 0; i < a->num_labels; i++) {
        if (strcmp(a->labels[i].name, name) == 0) {
            *out = a->labels[i].offset;
            return 0;
        }
    }
    return -1;
}

static int add_label(Assembler *a, const char *name, int32_t offset) {
    int32_t dummy;
    if (find_label(a, name, &dummy) == 0) {
        fprintf(stderr, "Duplicate label: %s\n", name);
        return -1;
    }
    if (a->num_labels >= MAX_LABELS) {
        fprintf(stderr, "Too many labels\n");
        return -1;
    }
    strncpy(a->labels[a->num_labels].name, name, LABEL_NAME_LEN - 1);
    a->labels[a->num_labels].offset = offset;
    a->num_labels++;
    return 0;
}

static int add_fixup(Assembler *a, const char *name, int32_t offset) {
    if (a->num_fixups >= MAX_FIXUPS) {
        fprintf(stderr, "Too many fixups\n");
        return -1;
    }
    strncpy(a->fixups[a->num_fixups].name, name, LABEL_NAME_LEN - 1);
    a->fixups[a->num_fixups].offset = offset;
    a->num_fixups++;
    return 0;
}

static int opcode_for(const char *mn) {
    if (!strcmp(mn, "HALT")) return OP_HALT;
    if (!strcmp(mn, "PUSH")) return OP_PUSH;
    if (!strcmp(mn, "POP")) return OP_POP;
    if (!strcmp(mn, "DUP")) return OP_DUP;
    if (!strcmp(mn, "SWAP")) return OP_SWAP;
    if (!strcmp(mn, "ADD")) return OP_ADD;
    if (!strcmp(mn, "SUB")) return OP_SUB;
    if (!strcmp(mn, "MUL")) return OP_MUL;
    if (!strcmp(mn, "DIV")) return OP_DIV;
    if (!strcmp(mn, "MOD")) return OP_MOD;
    if (!strcmp(mn, "EQ")) return OP_EQ;
    if (!strcmp(mn, "NE")) return OP_NE;
    if (!strcmp(mn, "LT")) return OP_LT;
    if (!strcmp(mn, "GT")) return OP_GT;
    if (!strcmp(mn, "LE")) return OP_LE;
    if (!strcmp(mn, "GE")) return OP_GE;
    if (!strcmp(mn, "JMP")) return OP_JMP;
    if (!strcmp(mn, "JZ")) return OP_JZ;
    if (!strcmp(mn, "JNZ")) return OP_JNZ;
    if (!strcmp(mn, "CALL")) return OP_CALL;
    if (!strcmp(mn, "RET")) return OP_RET;
    if (!strcmp(mn, "LOAD")) return OP_LOAD;
    if (!strcmp(mn, "STORE")) return OP_STORE;
    if (!strcmp(mn, "PRINT")) return OP_PRINT;
    return -1;
}

int asm_assemble(Assembler *a, const char *filename) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr, "Cannot open file: %s\n", filename);
        return 1;
    }
    char line[1024];
    while (fgets(line, sizeof(line), f)) {
        char *comment = strchr(line, ';');
        if (comment) *comment = '\0';
        char *tok = strtok(line, " \t\r\n");
        while (tok) {
            size_t len = strlen(tok);
            if (len > 0 && tok[len - 1] == ':') {
                tok[len - 1] = '\0';
                if (add_label(a, tok, a->code_len)) { fclose(f); return 1; }
                tok = strtok(NULL, " \t\r\n");
                continue;
            }
            break;
        }
        if (!tok) continue;
        int op = opcode_for(tok);
        if (op < 0) {
            fprintf(stderr, "Unknown mnemonic: %s\n", tok);
            fclose(f);
            return 1;
        }
        if (emit_byte(a, (uint8_t)op)) { fclose(f); return 1; }
        if (op == OP_PUSH) {
            char *arg = strtok(NULL, " \t\r\n");
            if (!arg) {
                fprintf(stderr, "PUSH requires an integer argument\n");
                fclose(f);
                return 1;
            }
            if (emit_i32(a, (int32_t)strtol(arg, NULL, 0))) { fclose(f); return 1; }
        } else if (op == OP_LOAD || op == OP_STORE) {
            char *arg = strtok(NULL, " \t\r\n");
            if (!arg) {
                fprintf(stderr, "%s requires an integer argument\n", tok);
                fclose(f);
                return 1;
            }
            if (emit_byte(a, (uint8_t)strtol(arg, NULL, 0))) { fclose(f); return 1; }
        } else if (op == OP_JMP || op == OP_JZ || op == OP_JNZ || op == OP_CALL) {
            char *arg = strtok(NULL, " \t\r\n");
            if (!arg) {
                fprintf(stderr, "%s requires a label argument\n", tok);
                fclose(f);
                return 1;
            }
            if (add_fixup(a, arg, a->code_len)) { fclose(f); return 1; }
            if (emit_i32(a, 0)) { fclose(f); return 1; }
        }
    }
    fclose(f);
    for (int i = 0; i < a->num_fixups; i++) {
        int32_t target;
        if (find_label(a, a->fixups[i].name, &target) != 0) {
            fprintf(stderr, "Undefined label: %s\n", a->fixups[i].name);
            return 1;
        }
        int32_t off = a->fixups[i].offset;
        for (int j = 0; j < 4; j++) {
            a->code[off + j] = (uint8_t)((target >> (8 * j)) & 0xff);
        }
    }
    return 0;
}
