#include <stdio.h>
#include <string.h>
#include "vm.h"
#include "asm.h"

int main(int argc, char **argv) {
    int trace = 0;
    const char *file = NULL;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 || strcmp(argv[i], "--trace") == 0) {
            trace = 1;
        } else {
            file = argv[i];
        }
    }
    if (!file) {
        fprintf(stderr, "Usage: %s <file.asm>\n", argv[0]);
        return 1;
    }
    Assembler a;
    asm_init(&a);
    if (asm_assemble(&a, file) != 0) {
        return 1;
    }
    VM vm;
    vm_init(&vm);
    vm_set_trace(&vm, trace);
    vm_load(&vm, asm_get_code(&a), asm_get_code_len(&a));
    return vm_run(&vm);
}
